import React from 'react';

export default function ClientLoginModal({ show, onClose, onLogin }) {
  if (!show) return null;

  const handleGoogleLogin = () => {
    // محاكاة تسجيل الدخول بجوجل
    const mockUser = {
      id: 'google-' + Date.now(),
      name: 'عميل جوجل',
      email: 'client@gmail.com',
      photo: 'https://cdn-icons-png.flaticon.com/512/2991/2991148.png',
      provider: 'google'
    };
    onLogin(mockUser);
  };

  const handleFacebookLogin = () => {
    // محاكاة تسجيل الدخول بفيسبوك
    const mockUser = {
      id: 'fb-' + Date.now(),
      name: 'عميل فيسبوك',
      email: 'client@facebook.com',
      photo: 'https://cdn-icons-png.flaticon.com/512/124/124010.png',
      provider: 'facebook'
    };
    onLogin(mockUser);
  };

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.6)', zIndex: 1080 }}>
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content shadow-lg border-0">
          <div className="modal-header border-0">
            <h5 className="modal-title fw-bold">👋 مرحباً بك</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body text-center p-4">
            <p className="text-muted mb-4">سجل الدخول لحفظ العقارات المفضلة ومتابعة طلباتك بسهولة.</p>
            
            <div className="d-grid gap-3">
              <button className="btn btn-outline-danger btn-lg d-flex align-items-center justify-content-center" onClick={handleGoogleLogin}>
                <span className="me-2">🔴</span> الاستمرار باستخدام Google
              </button>
              
              <button className="btn btn-outline-primary btn-lg d-flex align-items-center justify-content-center" onClick={handleFacebookLogin}>
                <span className="me-2">🔵</span> الاستمرار باستخدام Facebook
              </button>
            </div>
            
            <div className="mt-4 pt-3 border-top">
              <small className="text-muted">بالتسجيل أنت توافق على شروط الاستخدام وسياسة الخصوصية.</small>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
